/// The fixed native provider's operator door is separate from source-program commands: it reads
/// no capsule and accepts no caller-supplied time, target implementation or assessment.
fn price_provider_command(args: &[String]) -> Outcome {
    use capability::binding::CandidateBinding;
    use host::{ProviderReplacement, ProviderReplacementError};
    use world::resource::ResourceId;

    let mut values = std::collections::BTreeMap::new();
    let mut expect_empty = false;
    let mut words = args.iter();
    while let Some(flag) = words.next() {
        if flag == "--expect-empty" {
            if expect_empty {
                return failure("codara: price-provider: duplicate --expect-empty\n".to_owned());
            }
            expect_empty = true;
            continue;
        }
        if !matches!(
            flag.as_str(),
            "--data"
                | "--resource"
                | "--holding"
                | "--expected-provider"
                | "--expected-version"
                | "--token"
        ) {
            return failure("codara: price-provider: unsupported argument; only data, resource, Holding, expected binding and credential are accepted\n".to_owned());
        }
        let Some(value) = words.next() else {
            return failure(format!("codara: price-provider: {flag} needs a value\n"));
        };
        if values.insert(flag.as_str(), value.as_str()).is_some() {
            return failure(format!("codara: price-provider: duplicate {flag}\n"));
        }
    }
    let Some(data) = values.get("--data") else {
        return failure("codara: price-provider needs --data DIR\n".to_owned());
    };
    let on = match values
        .get("--resource")
        .and_then(|v| ResourceId::try_from(*v).ok())
    {
        Some(on) => on,
        None => {
            return failure(
                "codara: price-provider needs an existing --resource identifier\n".to_owned(),
            )
        }
    };
    let holding = match values
        .get("--holding")
        .and_then(|v| HoldingId::try_from(*v).ok())
    {
        Some(holding) => holding,
        None => {
            return failure(
                "codara: price-provider needs an existing --holding identifier\n".to_owned(),
            )
        }
    };
    let expected = match (expect_empty, values.get("--expected-provider"), values.get("--expected-version")) {
        (true, None, None) => None,
        (false, Some(provider), Some(version)) if !provider.is_empty() && !version.is_empty() => Some(CandidateBinding {
            provider: (*provider).to_owned(), version: (*version).to_owned(),
        }),
        _ => return failure("codara: price-provider needs exactly --expect-empty or both --expected-provider and --expected-version\n".to_owned()),
    };
    let token = values
        .get("--token")
        .map(|v| Presented::new(*v))
        .or_else(|| std::env::var(TOKEN_VARIABLE).ok().map(Presented::new));
    let Some(token) = token else {
        let mut report = Report::new();
        report.line("provider enrollment refused: effective current credential required");
        return report.end(exit::NOT_AUTHENTICATED);
    };
    let mut directory = match Directory::open(data) {
        Ok(directory) => directory,
        Err(_) => {
            return failure(
                "codara: price-provider: runtime directory could not be opened\n".to_owned(),
            )
        }
    };
    // Opening can wait for another process. Sample the trusted clock afterwards, never a
    // capsule's historical valid time, a --time value or a fallback timestamp of zero.
    let at = match std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()
        .and_then(|d| i64::try_from(d.as_millis()).ok())
        .map(Timestamp)
    {
        Some(at) => at,
        None => return failure("codara: price-provider: current clock unavailable\n".to_owned()),
    };
    let mut report = Report::new();
    report.line("codara price-provider");
    let who = match directory.host.authenticate(token.token(), at) {
        Ok(who) => who,
        Err(_) => {
            report.line("provider enrollment refused: effective current credential required");
            return report.end(exit::NOT_AUTHENTICATED);
        }
    };
    match directory.replace_price_text_provider(&who, &on, &holding, expected.as_ref(), at) {
        Ok(status) => {
            let status = match status {
                ProviderReplacement::Current => "current singleton",
                ProviderReplacement::AlreadyCurrent => "already current singleton",
            };
            report.line(format_args!("price provider: {status} at t{}; resource {}; Holding {}; provider kernel:{}; version 1", at.0, on, holding, capability_kernels::price_text::PRICE_TEXT_KERNEL));
            report.line("binding is technical availability; execution still requires current authority, admission, budget and validated evidence");
            report.end(exit::OK)
        }
        Err(ProviderReplacementError::KnownRefusal(_)) => {
            report.line("price provider refused: current credential scope, authority, Holding, expected binding and compiled implementation evidence must all hold");
            report.end(exit::NOT_ADMITTED)
        }
        Err(ProviderReplacementError::UnknownOrIncomplete(stage)) => {
            report.line(format_args!("price provider outcome unknown or incomplete at {stage:?}; this runtime handle is being dropped; reopen the runtime and inspect current binding before a separate operator decision"));
            drop(directory);
            report.end(exit::NOT_ACHIEVED)
        }
    }
}

// AUTHENTICATION: the principal the capsule runs as is a name until it is proved. This is the
// one place the command line opens the host for a run and knows who the run is for, so it is
// asked here, before the world is read and before anything is requested; a capsule that names
// no principal is refused further on, by the run, before anything is requested either.
if let Some(requester) = capsule.ir().requester() {
    let presented = invocation.token.as_ref().map(Presented::token);
    match run::authenticate_requester(&mut *world.host, requester, presented, setting.clock) {
        Ok(Some(proven)) => report.line(format_args!(
            "stage authentication: ok: the credential proves {proven} (authentication grants nothing: authority and admission are asked next)"
        )),
        Ok(None) => {}
        Err(refusal) => {
            report.line(format_args!(
                "stage authentication: refused: {refusal}; nothing was verified, nothing was requested"
            ));
            report.line(format_args!("ir digest: {}", capsule.semantic_digest()));
            return report.end(exit::NOT_AUTHENTICATED);
        }
    }
}

// Use the resource and request key the host actually executed, and authority now,
