                    report.line(format_args!("holding binding: persisted canonical evidence; holding {}; requester {}; resource {}", saved.holding, saved.requester, saved.resource));
                    saved.result
                })
        } else {
            lineara::work_receipt::result(&receipt).ok().flatten()
        }
    }
    lineara::record::EvidenceProof::Unobserved => None,

/// A data directory opened for a command: the host, which holds the directory lock until it
/// drops, and the capability graph the directory's declarations fold to, copied out so that the
/// host can be borrowed mutably (a run writes to it) while the graph is read. The directory
/// declares its graph through the host's door (`Host::declare_graph`) and in no other way; what
/// it holds is declared, never observed, and says so in [`Directory::origin`].
pub struct Directory {
    pub host: Host,
    pub graph: GraphView,
    /// Where the graph came from, as every output that depends on it says it.
    pub origin: String,
}

impl Directory {
    /// Enrolls the compiled bounded price-text provider through the existing authenticated Host door.
    /// `at` must be the caller's trusted current clock; graph declarations and assessments remain
    /// independent operator inputs. This does not grant execution authority or attest the artifact.
    pub fn replace_price_text_provider(
        &mut self,
        who: &PrincipalId,
        on: &ResourceId,
        holding: &HoldingId,
        expected: Option<&capability::binding::CandidateBinding>,
        at: Timestamp,
    ) -> Result<host::ProviderReplacement, host::ProviderReplacementError> {
        use capability::binding::CandidateBinding;
        use capability_kernels::price_text::{PRICE_TEXT_CAPABILITY, PRICE_TEXT_KERNEL};
        use genora_graph::capability_graph::Contract;
        use genora_graph::TransactionTime;
        let implementation = crate::declarations::price_implementation(PRICE_TEXT_KERNEL)
            .expect("fixed compiled price-text implementation");
        let operation: Contract =
            format!("{PRICE_TEXT_CAPABILITY}(input:bytes.any)->(output:bytes.any)")
                .parse()
                .expect("fixed price-text semantic contract");
        let current = self.host.graph().as_of(at, TransactionTime::LATEST);
        if current.node(implementation.id()).is_none()
            || !current.is_fact(implementation.id())
            || !current.is_fact(operation.id())
            || !current
                .providers_of(operation.id())
                .contains(&implementation.id())
            || !current.is_available(implementation.id())
        {
            return Err(host::ProviderReplacementError::KnownRefusal(HostError::Rejected(
            "the compiled price-text implementation lacks current independent VerifiedEvidence for its exact semantic operation".to_owned(),
        )));
        }
        let target = CandidateBinding {
            provider: format!("kernel:{PRICE_TEXT_KERNEL}"),
            version: "1".to_owned(),
        };
        self.host
            .replace_work_provider_in_holding(who, on, holding, expected, &target, at)
    }

/// What the durable stores record for this request's effect. This is not admission, proof of
/// canonicalization, or permission to retry. In particular, a run without a pending effect does
/// not prove that an effect was ever emitted or acknowledged.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RequestObservation {
    /// No durable Host WorkRun was found. This does not prove that a legacy provider never
    /// acted: providers without a native input binding historically ran before that snapshot.
    NotStarted,
    PendingUnknown {
        effect: EffectRef,
    },
    PendingEvidenced {
        effect: EffectRef,
    },
    NoPendingEffect {
        effect: EffectRef,
    },
}

/// Reads a request's recorded disposition without calling a provider, canonicalizing, or
/// acknowledging anything. The caller already holds the raw spine stores; this does not grant
/// observation rights over another resource. An unbound legacy run cannot be attributed to the
/// supplied request. The existing [`resume_request`] retains its separate legacy recovery rules.
pub fn observe_request<R: WorkRunStore, S: EvidenceStore>(
    runs: &R,
    evidence: &S,
    run_id: &WorkRunId,
    request: &RequestDigest,
) -> Result<RequestObservation, HostError> {
    let Some(run) = runs.restore(run_id).map_err(storage)? else {
        return Ok(RequestObservation::NotStarted);
    };
    if run.request() != Some(request) {
        return Err(HostError::RequestKeyReused(format!(
            "{run_id} is not bound to this request"
        )));
    }
    let effect = run.effect_ref(EFFECT);
    if !run.pending_effect_ids().contains(&EFFECT) {
        return Ok(RequestObservation::NoPendingEffect { effect });
    }
    let observed = evidence.get(&effect).map_err(storage)?;
    if observed.as_ref().is_some_and(|held| held.effect != effect) {
        return Err(HostError::Rejected(format!(
            "{run_id}: evidence names another effect"
        )));
    }
    Ok(match observed.map(|held| held.proof) {
        Some(EvidenceProof::ProviderAck(_)) => RequestObservation::PendingEvidenced { effect },
        Some(EvidenceProof::Unobserved) | None => RequestObservation::PendingUnknown { effect },
    })
}

/// A current local binding check, not an attestation of a historical operation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProviderReplacement {
    Current,
    AlreadyCurrent,
}

/// Where a binding write stopped with an uncertain or incomplete outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProviderReplacementStage {
    RetirePrevious,
    DeclareTarget,
    ReadBack,
}

#[derive(Debug)]
pub enum ProviderReplacementError {
    KnownRefusal(HostError),
    UnknownOrIncomplete(ProviderReplacementStage),
}

impl From<HostError> for ProviderReplacementError {
    fn from(error: HostError) -> Self {
        Self::KnownRefusal(error)
    }

/// terminating only the drain acts of the termination pass, and once it is terminated none
/// does (`host::presence`). Every public `&mut self` method but `authenticate` (which
/// changes only this session) calls it first (checked by the registry app's replica test,
/// which scans this file).
pub fn writable(&self) -> Result<(), HostError> {
    self.writable_directory()?;
    self.door_open()
}

/// Refuses a write on a read-only replica, or outside the office of an elected member: what
/// the directory itself allows, whatever the organism's presence is.
fn writable_directory(&self) -> Result<(), HostError> {
    if self.binding_write_uncertain {
        return Err(HostError::Rejected(
            "binding state is uncertain; reopen before any act".into(),
        ));
    }
    if let Some(leader) = &self.replica_of {
        return Err(HostError::ReadOnlyReplica(leader.clone()));
    }
    // A write here outside office would be acknowledged at local durability and could be
    // replaced as an uncommitted suffix by the next leader: it goes through the node.
    if self.elected_member && self.office.is_none() {
        return Err(HostError::Rejected(
            "this directory is a member of an elected cluster: only its leader writes, \
             through its node (`node-request`)"
                .into(),
        ));

/// Replaces this Holding's current local resource.work candidate. No authority, budget,
/// assessment or source-side custody is created. Separate durable appends are not atomic.
/// On uncertainty the Host closes its write door until reopened; recovery is a fresh act.
/// Singleton status holds only at `at`; scheduled future facts can change it. Existing
/// binding records contain no actor or operation record. Global unclassified or unknown
/// runs conservatively refuse this transition; nothing is inferred from zero pending.
pub fn replace_work_provider_in_holding(
    &mut self,
    who: &PrincipalId,
    on: &ResourceId,
    holding: &HoldingId,
    expected: Option<&CandidateBinding>,
    target: &CandidateBinding,
    at: Timestamp,
) -> Result<ProviderReplacement, ProviderReplacementError> {
    self.writable()?;
    let session = self.session.as_ref().ok_or(HostError::Unauthenticated)?;
    if &session.principal != who {
        return Err(HostError::Unauthenticated.into());
    }
    let credential = self
        .credentials
        .info(&session.accessor)
        .map_err(storage)?
        .ok_or(HostError::Unauthenticated)?;
    if &credential.principal != who
        || !credential.valid_at(at)
        || !credential.allows("capability.declare")
    {
        return Err(HostError::Unauthenticated.into());
    }
    self.require(who, "capability.declare", on, at)?;
    if self.holding_at(on, at)?.as_ref() != Some(holding) {
        return Err(HostError::Rejected(
            "provider replacement requires the current canonical Holding".into(),
        )
        .into());
    }
    if target.provider.trim().is_empty() || target.version.trim().is_empty() {
        return Err(HostError::Invalid(
            "provider replacement requires a nonempty provider and version".into(),
        )
        .into());
    }
    let act = action("resource.work")?;
    let current = self
        .capability
        .candidates_at(on, &act, at)
        .map_err(storage)?;
    let matches = match expected {
        None => current.is_empty(),
        Some(old) => current.as_slice() == std::slice::from_ref(old),
    };
    if !matches {
        return Err(HostError::Rejected(
            "provider replacement expected binding differs from the current local state".into(),
        )
        .into());
    }
    self.guard_work_provider_replacement(on, at)?;
    if let Some(old) = expected {
        if old == target {
            return Ok(ProviderReplacement::AlreadyCurrent);
        }
        if old.provider == target.provider {
            return Err(HostError::Rejected(
                "provider replacement cannot change a version under the same provider".into(),
            )
            .into());
        }
        if self
            .record_binding_retirement(&BindingRetirement::new(
                on.clone(),
                act.clone(),
                &old.provider,
                at,
            ))
            .is_err()
        {
            return Err(ProviderReplacementError::UnknownOrIncomplete(
                ProviderReplacementStage::RetirePrevious,
            ));
        }
    }
    if self
        .record_binding_declaration(
            &BindingDeclaration::new(on.clone(), act.clone(), target.clone()).since(at),
        )
        .is_err()
    {
        return Err(ProviderReplacementError::UnknownOrIncomplete(
            ProviderReplacementStage::DeclareTarget,
        ));
    }
    match self.capability.candidates_at(on, &act, at) {
        Ok(actual) if actual.as_slice() == std::slice::from_ref(target) => {
            Ok(ProviderReplacement::Current)
        }
        _ => {
            self.binding_write_uncertain = true;
            Err(ProviderReplacementError::UnknownOrIncomplete(
                ProviderReplacementStage::ReadBack,
            ))
        }
    }
}

fn record_binding_declaration(
    &mut self,
    declaration: &BindingDeclaration,
) -> Result<(), capability::resolution::CapabilityStoreError> {
    let outcome = self.capability.declare(declaration);
    if outcome.is_err() {
        self.binding_write_uncertain = true;
    }
    outcome
}

fn record_binding_retirement(
    &mut self,
    retirement: &BindingRetirement,
) -> Result<(), capability::resolution::CapabilityStoreError> {
    let outcome = self.capability.retire(retirement);
    if outcome.is_err() {
        self.binding_write_uncertain = true;
    }
    outcome

impl NativeWorkRunStore {
    pub fn open(path: impl AsRef<Path>) -> Result<Self, WorkRunLogError> {
        let (log, recovery) = RecordLog::open(path, MAGIC).map_err(WorkRunLogError::Log)?;
        let mut current = HashMap::new();
        for (index, bytes) in recovery.records.iter().enumerate() {
            let run = decode(bytes).map_err(|error| WorkRunLogError::Record { index, error })?;
            current.insert(run.id().clone(), run);
        }
        Ok(Self { log, current })
    }

    /// Every current snapshot, including unbound and pending runs, in unspecified order.
    /// This is a read-only view of the latest durable snapshot for each id; it neither
    /// attributes a run to a resource nor treats missing request provenance as quiescence.
    pub fn current_runs(&self) -> impl Iterator<Item = &WorkRun> {
        self.current.values()
    }
}

impl WorkRunStore for NativeWorkRunStore {
    fn snapshot(&mut self, run: &WorkRun) -> Result<(), WorkRunStoreError> {
        if let Some(stored) = self.current.get(run.id()) {
            if run.current_generation() < stored.current_generation() {
                return Err(WorkRunStoreError::Stale(format!(
                    "{} is at generation {:?}; a snapshot of {:?} is stale",
                    run.id(),
                    stored.current_generation(),
                    run.current_generation()
                )));
            }
            check_request(stored, run)?;
        }
        self.log
            .append(&encode(run))
            .map_err(|e| WorkRunStoreError::from(WorkRunLogError::Log(e)))?;
        self.current.insert(run.id().clone(), run.clone());
        Ok(())
    }

    let mut ids: Vec<u64> = run
        .pending_effect_ids()
        .into_iter()
        .map(|id| id.0)
        .collect();
    ids.sort_unstable();
    ids
}

#[test]
fn current_run_inventory_preserves_latest_unknown_fields_across_reopen_without_writes() {
    type InventoryRow = (String, u64, Option<[u8; 32]>, Vec<u64>);
    fn inventory(store: &NativeWorkRunStore) -> Vec<InventoryRow> {
        let mut rows: Vec<_> = store
            .current_runs()
            .map(|run| {
                (
                    run.id().as_str().to_owned(),
                    run.current_generation().0,
                    run.request().map(|request| request.0),
                    sorted_ids(run),
                )
            })
            .collect();
        rows.sort();
        rows
    }

    let p = path("inventory");
    let expected = vec![
        ("bound".to_owned(), 1, Some([17; 32]), vec![3, 9]),
        ("settled".to_owned(), 0, Some([23; 32]), vec![]),
        ("unbound".to_owned(), 7, None, vec![2, 8]),
    ];
    {
        let mut store = NativeWorkRunStore::open(&p).unwrap();
        let empty_bytes = std::fs::read(&p).unwrap();
        assert!(inventory(&store).is_empty());
        assert_eq!(std::fs::read(&p).unwrap(), empty_bytes);

        let mut bound = WorkRun::new(id("bound")).for_request(RequestDigest([17; 32]));
        bound.record_effect_emitted(EffectId(1));
        store.snapshot(&bound).unwrap();
        bound.record_effect_acknowledged(EffectId(1));
        bound.begin_retry().unwrap();
        bound.record_effect_emitted(EffectId(9));
        bound.record_effect_emitted(EffectId(3));
        store.snapshot(&bound).unwrap();
        let unbound = WorkRun::from_parts(
            id("unbound"),
            genora_primitives::Generation(7),
            [EffectId(8), EffectId(2)],
        );
        store.snapshot(&unbound).unwrap();
        let settled = WorkRun::new(id("settled")).for_request(RequestDigest([23; 32]));
        store.snapshot(&settled).unwrap();
        let bytes = std::fs::read(&p).unwrap();
        assert_eq!(inventory(&store), expected);
        assert_eq!(inventory(&store), expected);
        assert_eq!(std::fs::read(&p).unwrap(), bytes);
    }
    let bytes = std::fs::read(&p).unwrap();
    let store = NativeWorkRunStore::open(&p).unwrap();
    assert_eq!(inventory(&store), expected);
    for run in store.current_runs() {
        let restored = store.restore(run.id()).unwrap().unwrap();
        assert_eq!(restored.current_generation(), run.current_generation());
        assert_eq!(restored.request(), run.request());
        assert_eq!(sorted_ids(&restored), sorted_ids(run));
    }
    assert_eq!(std::fs::read(&p).unwrap(), bytes);
}

/// A physical shard of Chronica. The set is closed: these are the only repositories of the
/// ecosystem. Norl, the product, is not one of them: it is the whole Digital Holobiont, hosted by
/// the `chronica` shard, its cognitive ecology under `organism` (see
/// `schema::NORL_HOST_SHARD`, `schema::ECOLOGY_ROOT`). `domain` prefixes the semantic keys the importer proposes for a shard's legacy
/// nodes (keys are Chronica-wide; the prefix is semantic, never the repository name).
pub struct Shard {
    pub id: &'static str,
    pub origin: &'static str,
    pub domain: &'static str,
}

pub const SHARDS: &[Shard] = &[
    Shard {
        id: "ynventa",
        origin: "llgtrn/.Ynventa-",
        domain: "",
    },
    Shard {
        id: "chronica",
        origin: "llgtrn/Chronica",
        domain: "",
    },
    Shard {
        id: "atlas-studio",
        origin: "llgtrn/Atlas-Studio",
        domain: "compiler",
    },
    Shard {
        id: "universal-connector",
        origin: "llgtrn/Universal-Connector",
        domain: "connector",
    },
    Shard {
        id: "esellios",
        origin: "llgtrn/Esellios",
        domain: "commerce",
    },
    Shard {
        id: "fi-game",
        origin: "llgtrn/Fi-game",
        domain: "finance",
    },
    Shard {
        id: "mechatron",
        origin: "llgtrn/Mechatron",
        domain: "machine",
    },
];

pub fn shard(id: &str) -> Option<&'static Shard> {
    SHARDS.iter().find(|s| s.id == id)
}

/// The canonical shard of an origin (`llgtrn/Chronica`, any case).
pub fn shard_of_origin(origin: &str) -> Option<&'static Shard> {
    SHARDS
        .iter()
        .find(|s| s.origin.eq_ignore_ascii_case(origin))
}

/// Classifies exact native keys privately. Absence of pending effects alone proves nothing.
pub(super) fn guard_work_provider_replacement(
    &self,
    on: &ResourceId,
    at: Timestamp,
) -> Result<(), HostError> {
    let refusal =
        || HostError::Rejected("provider replacement requires known local quiescence".into());
    if self
        .runs
        .current_runs()
        .any(|run| run.request().is_none() || run.pending_effect_count() != 0)
    {
        return Err(refusal());
    }
    // Unlike materialize/show, this restore never publishes checkpoints or indexes.
    let reducers = crate::native_world_reducers().map_err(|_| refusal())?;
    let world = self
        .checkpoints
        .restore_or_rebuild_from_log(&self.world_log, &reducers)
        .map_err(|_| refusal())?;
    let mut known = std::collections::HashSet::new();
    let mut target_exists = false;
    for entity in world.entities() {
        let Some((state, _)) = state_of(Some(entity)).map_err(|_| refusal())? else {
            continue;
        };
        let target = state.id() == on;
        target_exists |= target;
        for (lease, held) in state.leases() {
            let probe = ResourceChange::Released {
                lease: lease.clone(),
            };
            self.guard_holding_work_lease_change(state.id(), &probe)
                .map_err(|_| refusal())?;
