fn replacement_real_synced_fault_closes_all_acts_until_reopen_and_fresh_enrollment() {
    for skip in [0, 1] {
        let mut site = Site::new();
        let issued = replacement_token(&mut site, None, None);
        let old = replacement_binding(PROVIDER);
        let new = replacement_binding("target-native-price");
        storage::faults::arm("record_log.append.synced", skip);
        let answer = replace(&mut site, Some(&old), &new, 20);
        let fired = storage::faults::fired();
        storage::faults::disarm();
        assert!(fired);
        let expected_stage = if skip == 0 {
            crate::ProviderReplacementStage::RetirePrevious
        } else {
            crate::ProviderReplacementStage::DeclareTarget
        };
        assert!(
            matches!(answer,Err(crate::ProviderReplacementError::UnknownOrIncomplete(stage)) if stage==expected_stage)
        );
        assert!(site.host.writable_directory().is_err());
        assert!(site.host.writable().is_err());
        assert!(site
            .host
            .bind_provider(
                &principal("root").unwrap(),
                &resource("cpu").unwrap(),
                &action("resource.work").unwrap(),
                PROVIDER,
                Timestamp(21)
            )
            .is_err());
        assert!(site
            .host
            .declare_holding(
                &principal("root").unwrap(),
                &resource("cpu").unwrap(),
                &HoldingId::try_from("escape").unwrap(),
                Timestamp(21)
            )
            .is_err());
        site.reopen();
        site.host
            .authenticate(&issued.token, Timestamp(21))
            .unwrap();
        let actual = site
            .host
            .capability
            .candidates_at(
                &resource("cpu").unwrap(),
                &action("resource.work").unwrap(),
                Timestamp(21),
            )
            .unwrap();
        if skip == 0 {
            assert!(actual.is_empty());
            assert_eq!(
                replace(&mut site, None, &new, 21).unwrap(),
                crate::ProviderReplacement::Current
            );
        } else {
            assert_eq!(actual, vec![new.clone()]);
            assert_eq!(
                replace(&mut site, Some(&new), &new, 21).unwrap(),
                crate::ProviderReplacement::AlreadyCurrent
            );
        }
    }
}

