fn pin(root: &Path, e: &Expect) -> Result<(), String> {
    require(
        hex(&e.commit, 40) && hex(&e.tree, 40),
        "full lowercase commit/tree pins required",
    )?;
    require(
        e.channel == "refs/heads/main",
        "expected channel must be the supported main association",
    )?;
    let bytes = local_git(root, &["cat-file", "commit", &e.commit], 1 << 20)?;
    let header = std::str::from_utf8(&bytes)
        .map_err(|_| "TARGET_REFERENCE: non-UTF8 commit")?
        .split_once("\n\n")
        .ok_or("TARGET_REFERENCE: missing commit headers")?
        .0;
    let trees: Vec<_> = header
        .lines()
        .filter_map(|s| s.strip_prefix("tree "))
        .collect();
    require(trees == [e.tree.as_str()], "commit/tree mismatch")?;
    require(
        local_git(root, &["cat-file", "-t", &e.tree], 128)? == b"tree\n",
        "pin is not a tree",
    )

fn blob(
    root: &Path,
    entries: &BTreeMap<String, Entry>,
    path: &str,
    expected: &str,
) -> Result<Vec<u8>, String> {
    require(
        normal(path) && hex(expected, 64),
        "invalid bound path or raw SHA-256",
    )?;
    let entry = entries
        .get(path)
        .ok_or_else(|| format!("TARGET_REFERENCE: absent pinned input {path}"))?;
    require(
        matches!(entry.mode.as_str(), "100644" | "100755"),
        "pinned input must be a regular blob",
    )?;
    let bytes = local_git(root, &["cat-file", "blob", &entry.oid], MAX_BLOB)?;
    require(
        &content_digest(&bytes)[7..] == expected,
        "pinned input SHA-256 mismatch",
    )?;
    Ok(bytes)

/// Independently supplied publication and implementation pins are deliberately separate.
/// `contract.path` is the actual Chronica publication path, not ECDEV's local copied path.
/// Reads every input that the published owner reference pins, retaining exact raw bytes.
pub fn qualify_local_git(
    root: &Path,
    publication: &Expect,
    implementation: &Expect,
    contract: &Witness,
) -> Result<TargetReference, String> {
    pin(root, publication)?;
    pin(root, implementation)?;
    let published = inventory(root, &publication.commit)?;
    let raw = blob(root, &published, &contract.path, &contract.sha256)?;
    let parsed = json::parse_unique(
        std::str::from_utf8(&raw).map_err(|_| "TARGET_REFERENCE: contract is not UTF-8")?,
    )?;
    require(
        text(&parsed, "classification")? == CLASS,
        "unsupported target reference classification",
    )?;
    let reference = field(&parsed, "target_repository_pin")?;
    let target = field(&parsed, "target")?;
    for v in [reference, target] {
        require(
            text(v, "repository")? == "llgtrn/Chronica"
                && text(v, "commit")? == implementation.commit
                && text(v, "tree")? == implementation.tree,
            "independent implementation pin differs from reference",
        )?;
    }
    require(
        text(reference, "ref")? == implementation.channel,
        "reference channel association differs",
    )?;
    let entries = inventory(root, &implementation.commit)?;
    let inputs = field(&parsed, "pinned_target_inputs")?
        .table()
        .ok_or("TARGET_REFERENCE: input table required")?;
    require(
        !inputs.is_empty() && inputs.len() <= 128,
        "input table exceeds bound or is empty",
    )?;
    let mut retained = BTreeMap::new();
    let mut total = 0usize;
    for (path, expected) in inputs {
        let bytes = blob(root, &entries, path, text(expected, "sha256")?)?;
        require(
            entries[path].oid == text(expected, "git_blob")?,
            "input Git blob mismatch",
        )?;
        total = total
            .checked_add(bytes.len())
            .ok_or("TARGET_REFERENCE: input size overflow")?;
        require(total <= MAX_TOTAL, "total input bound exceeded")?;
        retained.insert(path.clone(), bytes);
    }
    let declaration = retained
        .get(DECLARATION)
        .ok_or("TARGET_REFERENCE: exact owner declaration required")?;

    let artifact = field(target, "source_artifact")?;
    let path = text(artifact, "path")?;
    require(
        path.starts_with(&format!("{}/", owner.path)),
        "implementation is outside its existing owner",
    )?;
    let claims: Vec<_> = repo
        .nodes
        .iter()
        .filter(|n| {
            schema::is_physical(n.kind)
                && !n.path.is_empty()
                && (path == n.path || path.starts_with(&format!("{}/", n.path)))
        })
        .collect();
    let depth = claims.iter().map(|n| n.path.len()).max();
    let deepest: Vec<_> = claims
        .into_iter()
        .filter(|n| Some(n.path.len()) == depth)
        .collect();
    require(
        deepest.len() == 1 && deepest[0].key == owner.key,
        "implementation has a different or ambiguous physical owner",
    )?;
    let source = retained
        .get(path)
        .ok_or("TARGET_REFERENCE: pinned implementation input missing")?;
    require(
        content_digest(source) == text(artifact, "digest")?,
        "implementation source digest mismatch",
    )?;
    let map = field(field(&parsed, "bounded_coverage")?, "case_map")?;
    let case_map_path = text(map, "path")?.to_string();
    let bytes = retained
        .get(&case_map_path)
        .ok_or("TARGET_REFERENCE: pinned case-map input missing")?;
    require(
        &content_digest(bytes)[7..] == text(map, "sha256")?,
        "case-map digest mismatch",
    )?;
    Ok(TargetReference {
        publication: publication.clone(),
        implementation: implementation.clone(),
        contract_digest: content_digest(&raw),
        contract: raw,
        inputs: retained,
        case_map_path,
    })
}

/// Verify the complete *supplied capture* against independently selected immutable source
/// objects. Uncaptured native code, UI/assets and the producer graph remain visible limits.
/// This does not parse source dialect as canonical declarations or install a registry entry.
pub fn qualify_source_local_git(
    root: &Path,
    expected: &Expect,
    checked: &super::Checked,
) -> Result<SourceReference, String> {
    pin(root, expected)?;
    let source = &checked.source().source;
    require(
        source.source_repository == "llgtrn/ECDEV"
            && source.source_id == "ecdev"
            && source.observed_head == expected.commit,
        "source capture differs from independently selected source commit",
    )?;
    let entries = inventory(root, &expected.commit)?;
    let mut total = 0usize;
    for (path, file) in &source.snapshot.files {
        require(path == &file.path, "captured source path identity differs")?;
        let digest = file
            .digest
            .strip_prefix("sha256:")
            .ok_or("TARGET_REFERENCE: source file digest has no domain")?;
        let bytes = blob(root, &entries, path, digest)?;
        require(
            bytes == file.bytes,
            "captured source bytes differ from pinned commit",
        )?;
        total = total
            .checked_add(bytes.len())
            .ok_or("TARGET_REFERENCE: source size overflow")?;
        require(total <= MAX_TOTAL, "captured source byte bound exceeded")?;
    }
    Ok(SourceReference {
        pin: expected.clone(),
        capture_digest: source.envelope_digest.clone(),
        captured_files: source.snapshot.files.len(),
        captured_bytes: total,
        committed_files: entries.len(),
    })
}

