/// decoded ordering/coverage and all source-derived claims must match the existing contract.
/// The producer currently defines only null target objects. A real independently supplied
/// owner pin does not authorize this reader to invent the absent positive-target wire schema.
pub fn inspect_bound(
    capture_bytes: &[u8],
    capture_sha256: &str,
    proposal_bytes: &[u8],
    proposal_sha256: &str,
) -> Result<CheckedProposal, String> {
    if proposal_bytes.len() > MAX_PROPOSAL_BYTES {
        return Err("PROPOSAL_READER_BUDGET_EXCEEDED".into());
    }
    if proposal_sha256.len() != 64 || !proposal_sha256.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err("expected proposal SHA256 must be 64 hex digits".into());
    }
    let digest = content_digest(proposal_bytes);
    if !digest[7..].eq_ignore_ascii_case(proposal_sha256) {
        return Err("PROPOSAL_DIGEST_MISMATCH".into());
    }
    let text = std::str::from_utf8(proposal_bytes).map_err(|e| e.to_string())?;
    let proposal = json::parse(text)?;
    super::super::dependency::unique_json_keys(text)?;
    let source = portable::parse_bound(capture_bytes, capture_sha256)?;
    if get(&proposal, "target_custody")? != &Value::Null
        || array(&proposal, "node_mappings")?
            .iter()
            .any(|m| m.get("proposed_target") != Some(&Value::Null))
    {
        return Err("UNSUPPORTED_TARGET_CONTRACT: v1 producer defines only null targets; coordinate positive producer fields and independent owner/custody before enrollment".into());
    }
    let expected = json::parse(&expected_pending(&source)?.render())?;
    if proposal != expected {
        return Err("PROPOSAL_SOURCE_BINDING_OR_COVERAGE_DRIFT".into());
    }
    let report = Report {
        capture_digest: source.envelope_digest.clone(),
        proposal_digest: digest,
        source_nodes: source.source_graph.nodes.len(),
        payloads: source.snapshot.files.len(),
        rights_claims: source.snapshot.donor_keys.len(),
        global_identity_candidates: source
            .source_graph
            .nodes
            .iter()
            .filter(|n| n.namespace == "oss")
            .count(),
        enrollment_credit: 0,
        grammar_conformance: Assessment::NotAssessed,
        migration_readiness: Assessment::Blocked,
        native_caller_integration: Assessment::NotRun,
        source_retirement: Assessment::NotQualified,
        unresolved_reasons: REASONS.iter().map(|v| v.to_string()).collect(),
    };
    Ok(CheckedProposal {

