pub const FORMAT: &str = "ecdev-bounded-price-mapping-v1";
const MAX_BYTES: usize = 16 * 1024 * 1024;
const NEW: [usize; 7] = [117, 212, 409, 855, 1188, 1193, 1849];
const SELECTORS: [&str; 4] = [
    "input",
    "currency_hint",
    "decimal_separator",
    "digit_group_separator",
];
const NEW_MANIFEST: &str = "5beaf6ab248dde7a3c42e6ef1b177c64e8c3af481561e5dd2d76aa2d893d342e";
const ALL_MANIFEST: &str = "451f0bb1a2f3acd3879ddc2945c14e74447ec6ac70dfd5ebf374d086c8f353dc";
const OLD_MANIFEST: &str = "d5794485dd05bcb51e79fcc5af2a0ea6a1a915800a829ee0211cd3df985df29f";

/// Every expected digest is supplied independently by the caller, never read from the
/// artifact being qualified. A digest is transport integrity, not authenticated custody.
#[derive(Clone, Copy, Debug)]
pub struct BoundBytes<'a> {
    pub bytes: &'a [u8],
    pub sha256: &'a str,
}
#[derive(Clone, Copy, Debug)]
pub struct Inputs<'a> {
    pub capture: BoundBytes<'a>,
    pub proposal: BoundBytes<'a>,
    pub candidate: BoundBytes<'a>,
    pub owner_contract: BoundBytes<'a>,
    pub case_map: Option<BoundBytes<'a>>,
    /// Independent raw index/name metadata; never grants execution or enrollment.
    pub all106_name_manifest: Option<BoundBytes<'a>>,
}

/// Validate the bounded reference against independently supplied complete source and owner
/// inputs. This function executes no source program and does not authenticate Git custody.
pub fn inspect_bound(inputs: Inputs<'_>) -> Result<Checked, String> {
    let source = proposal::inspect_bound(
        inputs.capture.bytes,
        inputs.capture.sha256,
        inputs.proposal.bytes,
        inputs.proposal.sha256,
    )?;
    let (v, digest) = parse(inputs.candidate)?;
    let (owner, owner_digest) = parse(inputs.owner_contract)?;
    object(
        &v,
        &[
            "format",
            "scope",
            "source_mapping",
            "source_bindings",
            "source_caller",
            "node_mappings",
            "target_contract",
            "target_custody",
            "target_owner_statement",
            "declared_owner_verification",
            "owner_membership_artifact",
            "target_contract_status_dimensions",
            "target_reported_caller_evidence",
            "coverage",
            "old99",
            "new_candidates",
            "historical_subset_publication",
            "exact_input_output_and_admission",
            "canonical_assignment",
            "accepted_owner",
            "authority",
            "authority_grants",
            "copying_authorization",
            "current_rights",
            "build_assessment",
            "binary_attestation",
            "world_admission",
            "admission",
            "source_adapter_cutover",
            "governed_caller_locally_run",
            "source8_registry",
        ],
    )?;
    text(&v, "format", FORMAT)?;
    text(
        &v,
        "scope",
        "PROPOSED_106_CASE_SUBDOMAIN_ONLY; NO_CANONICAL_ASSIGNMENT_OR_ADMISSION",
    )?;
    pending(&v)?;
    if source.source.source_graph.nodes.len() != 828 || source.source.snapshot.files.len() != 734 {
        return Err(fail(
            "bounded version requires complete 734-file/828-node current source",
        ));

    source_bindings(&v, &source, &owner)?;
    target_copies(&v, &owner, &owner_digest)?;
    historical(&v, &owner)?;
    let coverage = coverage(&v, &owner, inputs.case_map)?;
    let all106_name_manifest = qualify_manifest(&v, inputs.all106_name_manifest)?;
    let mut missing_inputs = Vec::new();
    if inputs.all106_name_manifest.is_none() {
        missing_inputs
            .push("INDEPENDENTLY_BOUND_FROZEN_MANIFEST_REQUIRED_FOR_ALL106_NAME_MANIFEST".into());
    }
    if inputs.case_map.is_none() {
        missing_inputs.push("INDEPENDENTLY_BOUND_TARGET_CASE_MAP_REQUIRED_FOR_COVERAGE".into());
    }
    Ok(Checked {
        source,
        original_candidate_bytes: inputs.candidate.bytes.to_vec(),
        original_owner_contract_bytes: inputs.owner_contract.bytes.to_vec(),
        original_case_map_bytes: inputs.case_map.map(|m| m.bytes.to_vec()),
        original_all106_name_manifest_bytes: inputs.all106_name_manifest.map(|m| m.bytes.to_vec()),
        candidate: v,
        owner_contract: owner,
        report: Report {
            candidate_sha256: digest,
            target_contract_sha256: owner_digest,
            coverage,
            all106_name_manifest,
            missing_inputs,
        },
    })
}

/// Compose byte-level reference checks with the separately constructed immutable Git
/// membership witness. The caller must supply exactly the same contract and case-map bytes.
pub fn qualify_with_target(
    inputs: Inputs<'_>,
    target: &target::TargetReference,
) -> Result<Checked, String> {
    if inputs.owner_contract.bytes != target.contract_bytes()
        || !inputs
            .owner_contract
            .sha256
            .eq_ignore_ascii_case(target.contract_sha256())
        || inputs
            .case_map
            .is_none_or(|m| m.bytes != target.case_map_bytes())
    {
        return Err(fail(
            "independent target reference differs from supplied inputs",
        ));
    }
    let checked = inspect_bound(inputs)?;
    let contract = get(checked.candidate(), "target_contract")?;
    text(contract, "publication_commit", &target.publication().commit)?;
    text(contract, "publication_tree", &target.publication().tree)?;
    // Implementation pin is separately verified by target::qualify_local_git; it is
    // deliberately distinct from the contract's publication commit/tree.
    let proposed = get(
        &array(checked.candidate(), "node_mappings")?[0],
        "proposed_target",
    )?;
    text(proposed, "commit", &target.implementation().commit)?;
    text(proposed, "tree", &target.implementation().tree)?;
    Ok(checked)
